/* ---------- 释放整棵树（已提供）---------- */
static void free_tree(BPTreeNode *root) {
    if (root == NULL) return;
    if (!root->is_leaf) {
        for (int i = 0; i <= root->num_keys; i++) free_tree(root->children[i]);
    }
    free(root);
}

